#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>
#include <bitset>

using namespace std;

typedef long long ll;
const int MAXN = 66;

int rows, cols, total_len, idx;
char str[MAXN];
ll comb[MAXN][MAXN];

int cntA[MAXN], cntB[MAXN];
vector<ll> part[MAXN], partZero[MAXN];

void precompute_comb() {
    for (int i = 0; i <= total_len; ++i) {
        comb[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            comb[i][j] = comb[i-1][j-1] + comb[i-1][j];
    }
}

ll compute_diffs(int config, int a_before, int b_before) {
    ll ans = 0;
    for (int i = 0; i < cols + 1; ++i) {
        if (config & (1 << i)) {
            ++b_before;
            ll aux1 = comb[b_before - 1][rows - 1];
            ll aux2 = comb[total_len - b_before][rows] - comb[a_before][rows];
            ans -= aux1 * aux2;
        } else {
            ++a_before;
            ll aux1 = comb[a_before - 1][rows - 1];
            ll aux2 = comb[total_len - a_before][rows] - comb[b_before][rows];
            ans += aux1 * aux2;
        }
    }
    return ans;
}

bool is_valid(int config) {
    for (int i = 0; i < cols + 1; ++i) {
        if (str[2 * rows + cols + i] == 'A' && ((config >> i) & 1) == 1) return false;
        if (str[2 * rows + cols + i] == 'B' && ((config >> i) & 1) == 0) return false;
    }
    return true;
}

void build_second_part() {
    int limit = 1 << (cols + 1);
    for (int config = 0; config < limit; ++config) {
        bitset<66> bits(config);
        int b_cnt = bits.count();
        int a_cnt = cols + 1 - b_cnt;
        ll val = compute_diffs(config, rows + cols - a_cnt, rows + cols - b_cnt);
        if (is_valid(config))
            part[a_cnt].push_back(val);
        else
            partZero[a_cnt].push_back(val);
    }
    for (int i = 0; i <= cols + 1; ++i) {
        sort(part[i].begin(), part[i].end());
        sort(partZero[i].begin(), partZero[i].end());
    }
}

ll get_coefficient(int config) {
    int i, j;
    for (i = 0; i < cols + 1; ++i)
        if (((config >> i) & 1) != (config & 1))
            break;
    for (j = i; j < cols + 1; ++j) {
        if (str[2 * rows - 1 + j] == 'A' && ((config >> j) & 1) == 1) return 0;
        if (str[2 * rows - 1 + j] == 'B' && ((config >> j) & 1) == 0) return 0;
    }
    int setA = rows - 1 + ((config & 1) == 0 ? i : 0);
    int setB = rows - 1 + ((config & 1) == 1 ? i : 0);
    if (setA < cntA[2 * rows - 2 + i]) return 0;
    if (setB < cntB[2 * rows - 2 + i]) return 0;
    return comb[setA + setB - cntA[2 * rows - 2 + i] - cntB[2 * rows - 2 + i]][setA - cntA[2 * rows - 2 + i]];
}

void update_best(pair<ll, ll>& best, pair<ll, ll> candidate) {
    if (candidate.first < 0) candidate.first = -candidate.first;
    if (best.first < candidate.first) return;
    if (best.first > candidate.first) {
        best = candidate;
        return;
    }
    best.second += candidate.second;
}

ll count_occurrences(vector<ll>& data, ll val) {
    auto range = equal_range(data.begin(), data.end(), val);
    return range.second - range.first;
}

ll compute_first_part() {
    int limit = 1 << (cols + 1);
    pair<ll, ll> best = make_pair(1LL << 60, 0);
    for (int config = 0; config < limit; ++config) {
        bitset<66> bits(config);
        int b_cnt = bits.count();
        int a_cnt = cols + 1 - b_cnt;
        ll act = compute_diffs(config, rows - 1, rows - 1);
        ll coef = get_coefficient(config);
        auto it = lower_bound(part[cols + 1 - a_cnt].begin(), part[cols + 1 - a_cnt].end(), -act);
        if (it != part[cols + 1 - a_cnt].end()) {
            if (best.first >= abs(*it + act)) {
                ll cnt = count_occurrences(part[cols + 1 - a_cnt], *it);
                update_best(best, make_pair(*it + act, coef * cnt));
            }
        }
        if (it != part[cols + 1 - a_cnt].begin()) {
            --it;
            if (best.first >= abs(*it + act)) {
                ll cnt = count_occurrences(part[cols + 1 - a_cnt], *it);
                update_best(best, make_pair(*it + act, coef * cnt));
            }
        }
        coef = 0;
        it = lower_bound(partZero[cols + 1 - a_cnt].begin(), partZero[cols + 1 - a_cnt].end(), -act);
        if (it != partZero[cols + 1 - a_cnt].end()) {
            if (best.first >= abs(*it + act)) {
                ll cnt = count_occurrences(part[cols + 1 - a_cnt], *it);
                update_best(best, make_pair(*it + act, coef * cnt));
            }
        }
        if (it != partZero[cols + 1 - a_cnt].begin()) {
            --it;
            if (best.first >= abs(*it + act)) {
                ll cnt = count_occurrences(part[cols + 1 - a_cnt], *it);
                update_best(best, make_pair(*it + act, coef * cnt));
            }
        }
    }
    return best.second;
}

int main() {
    scanf("%d%d\n%s", &rows, &cols, str + 1);
    total_len = 2 * (rows + cols);
    precompute_comb();
    for (idx = 1; idx <= total_len; ++idx) {
        cntA[idx] = cntA[idx-1] + (str[idx] == 'A' ? 1 : 0);
        cntB[idx] = cntB[idx-1] + (str[idx] == 'B' ? 1 : 0);
    }
    build_second_part();
    ll solution = compute_first_part();
    printf("%lld", solution);
    return 0;
}
